files.content:
.group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.inline {
  flex-direction: row;
  flex-wrap: wrap;
  gap: 8px 22px;
}

.cards {
  display: grid;
  grid-template-columns: repeat(var(--columns, 2), minmax(0, 1fr));
  gap: 10px;
}

@media (max-width: 640px) {
  .cards {
    grid-template-columns: 1fr;
  }
}

.item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 11px;
  cursor: pointer;
  color: var(--ink-body);
}

.input {
  position: absolute;
  width: 18px;
  height: 18px;
  margin: 0;
  opacity: 0;
  cursor: inherit;
}

.dot {
  position: relative;
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  margin-top: 1px;
  border-radius: 50%;
  background: var(--surface-solid);
  box-shadow: inset 0 0 0 1.5px var(--neutral-border);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease);
}

.dot::after {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  background: var(--surface-solid);
  opacity: 0;
  transition: opacity var(--dur) var(--ease);
}

.item:hover .input:not(:disabled):not(:checked) + .dot {
  box-shadow: inset 0 0 0 1.5px var(--brand), 0 0 0 3px rgba(var(--rgb-brand), 0.1);
}

.input:checked + .dot {
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
}

.input:checked + .dot::after {
  opacity: 1;
}

.input:focus-visible + .dot {
  box-shadow: var(--focus-ring);
}

.invalid .input:not(:checked) + .dot {
  background: var(--danger-field-fill);
  box-shadow: inset 0 0 0 1.5px var(--danger-base);
}

.disabled {
  cursor: not-allowed;
}

.input:disabled + .dot {
  background: var(--surface-sunken);
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand-deep), 0.16);
}

.input:disabled:checked + .dot {
  background: rgba(var(--rgb-brand-deep), 0.22);
}

.disabled .label,
.disabled .description {
  color: var(--ink-disabled);
}

.text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.label {
  font-size: var(--text-body);
  line-height: 1.5;
}

.description {
  font-size: var(--text-caption);
  line-height: 1.5;
  color: var(--ink-muted);
}

/* ── Choice cards ───────────────────────────────────────────────────────── */

.cards .item {
  padding: 14px 16px;
  border-radius: var(--r-lg);
  background: rgba(var(--rgb-white), 0.72);
  box-shadow: inset 0 0 0 1px var(--line), 0 1px 2px rgba(var(--rgb-contact), 0.04);
  transition:
    background-color var(--dur) var(--ease),
    box-shadow var(--dur) var(--ease),
    transform var(--dur) var(--ease);
}

.cards .input {
  top: 15px;
  left: 16px;
}

.cards .item:hover:not(.disabled) {
  background: var(--surface-solid);
  box-shadow: inset 0 0 0 1px rgba(var(--rgb-brand), 0.3), 0 3px 10px rgba(var(--rgb-brand-deep), 0.08);
  transform: translateY(-1px);
}

.cards .item:has(.input:checked) {
  background: linear-gradient(135deg, rgba(var(--rgb-brand), 0.09), rgba(var(--rgb-brand-deep), 0.04)), var(--surface-solid);
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand), 0.6), 0 3px 10px rgba(var(--rgb-brand), 0.12);
  transform: none;
}

.cards .item:has(.input:focus-visible) {
  box-shadow: inset 0 0 0 1.5px rgba(var(--rgb-brand), 0.6), 0 0 0 3px rgba(var(--rgb-brand), 0.2);
}

.cards .item.invalid:not(:has(.input:checked)) {
  background: var(--danger-field-fill);
  box-shadow: inset 0 0 0 1px rgba(var(--rgb-danger), 0.55);
}

.cards .label {
  font-weight: 700;
  color: var(--ink-heading);
}

.cards .description {
  font-size: var(--text-small);
}

"use client";

import { useId, type CSSProperties, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { mergeDescribedBy, useField } from "../Field/Field";
import styles from "./RadioGroup.module.css";

export type RadioOption<V extends string = string> = {
  value: V;
  label: ReactNode;
  description?: ReactNode;
  disabled?: boolean;
};

export type RadioGroupProps<V extends string = string> = {
  options: ReadonlyArray<RadioOption<V>>;
  value: V | null;
  onChange: (value: V) => void;
  /** Shared native name. Generated if omitted; arrow keys work across the group natively. */
  name?: string;
  /**
   * list   = stacked radios.
   * inline = radios in a row (Yes / No).
   * cards  = choice cards: title + description tiles (withdrawal source,
   *          delivery destination).
   */
  variant?: "list" | "inline" | "cards";
  /** cards only. Collapses to one column under 640px. */
  columns?: 1 | 2 | 3;
  invalid?: boolean;
  disabled?: boolean;
  required?: boolean;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  className?: string;
};

/** Wrap in <Field group> for the legend, hint and error. */
export function RadioGroup<V extends string = string>({
  options,
  value,
  onChange,
  name: nameProp,
  variant = "list",
  columns = 2,
  invalid: invalidProp,
  disabled,
  required,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  className,
}: RadioGroupProps<V>) {
  const field = useField();
  const autoId = useId();
  const name = nameProp ?? `radio-${autoId}`;
  const invalid = invalidProp ?? field?.invalid ?? false;

  return (
    <div data-slot="radio-group"
      role="radiogroup"
      aria-label={ariaLabel}
      aria-labelledby={ariaLabel ? undefined : (ariaLabelledBy ?? field?.labelId)}
      aria-describedby={mergeDescribedBy(field?.describedBy)}
      aria-required={required ?? field?.required ?? undefined}
      aria-invalid={invalid || undefined}
      className={cx(styles.group, styles[variant], className)}
      style={variant === "cards" ? ({ "--columns": columns } as CSSProperties) : undefined}
    >
      {options.map((option, i) => {
        const id = `${name}-${i}`;
        const descId = option.description ? `${id}-desc` : undefined;
        const isDisabled = disabled || option.disabled;
        return (
          <label
            key={option.value}
            htmlFor={id}
            className={cx(styles.item, invalid && styles.invalid, isDisabled && styles.disabled)}
          >
            <input
              id={id}
              type="radio"
              name={name}
              value={option.value}
              checked={value === option.value}
              onChange={() => onChange(option.value)}
              disabled={isDisabled}
              aria-describedby={descId}
              className={styles.input}
            />
            <span className={styles.dot} aria-hidden="true" />
            <span className={styles.text}>
              <span className={styles.label}>{option.label}</span>
              {option.description ? (
                <span id={descId} className={styles.description}>
                  {option.description}
                </span>
              ) : null}
            </span>
          </label>
        );
      })}
    </div>
  );
}
